package in.sih.dementia.auth;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import java.nio.charset.StandardCharsets; import java.time.Instant; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service class JwtService { private final byte[] key; private final long expiryMinutes; JwtService(@Value("${app.jwt.secret}") String secret,@Value("${app.jwt.expiration-minutes}") long expiryMinutes){this.key=secret.getBytes(StandardCharsets.UTF_8);this.expiryMinutes=expiryMinutes;} String issue(User u){var now=Instant.now();return Jwts.builder().subject(u.getId().toString()).claim("role",u.getRole().name()).issuedAt(Date.from(now)).expiration(Date.from(now.plusSeconds(expiryMinutes*60))).signWith(Keys.hmacShaKeyFor(key)).compact();} Claims parse(String token){return Jwts.parser().verifyWith(Keys.hmacShaKeyFor(key)).build().parseSignedClaims(token).getPayload();} }
